from google.cloud import storage
import os

def get_storage_client(project_id: str):
    return storage.Client(project=project_id)

def get_bucket_name():
    return os.environ.get("GCS_BUCKET_NAME", "your-gcs-bucket-name")

def get_project_id():
    return os.environ.get("GCP_PROJECT_ID", "your-gcp-project-id")

from dataclasses import dataclass, field
from typing import Optional, Dict, Any

@dataclass
class UploadObjectRequest:
    object_name: str
    data: bytes
    content_type: Optional[str] = "application/octet-stream"

@dataclass
class UploadObjectResponse:
    object_name: str

@dataclass
class PresignedDownloadRequest:
    object_name: str
    expiration_seconds: int = 3600 # 1 hour

@dataclass
class PresignedDownloadResponse:
    url: str

@dataclass
class ObjectMetadataRequest:
    object_name: str

@dataclass
class ObjectMetadataResponse:
    object_name: str
    size: int
    content_type: Optional[str]
    etag: Optional[str]
    updated: Optional[str]
    metadata: Optional[Dict[str, str]] = field(default_factory=dict)

@dataclass
class ListPrefixRequest:
    prefix: str = ""
    delimiter: Optional[str] = None

@dataclass
class ListPrefixResponse:
    objects: list[str] = field(default_factory=list)
    prefixes: list[str] = field(default_factory=list)

from storage_client import get_storage_client, get_bucket_name, get_project_id
from storage_models import ListPrefixRequest, ListPrefixResponse

def list_prefix(payload: ListPrefixRequest):
    client = get_storage_client(get_project_id())
    bucket = client.bucket(get_bucket_name())

    blobs = client.list_blobs(bucket, prefix=payload.prefix, delimiter=payload.delimiter)

    objects = []
    for blob in blobs:
        objects.append(blob.name)

    prefixes = []
    for prefix in blobs.prefixes:
        prefixes.append(prefix)

    return ListPrefixResponse(objects=objects, prefixes=prefixes)

from google.cloud import vision
from google.cloud import storage
from storage_client import get_bucket_name, get_project_id

def stored_document_ocr(gcs_object_name: str):
    client = vision.ImageAnnotatorClient()

    image = vision.Image(
        source=vision.ImageSource(gcs_image_uri=f"gs://{get_bucket_name()}/{gcs_object_name}")
    )

    response = client.text_detection(image=image)
    texts = response.text_annotations

    if texts:
        return {"extracted_text": texts[0].description}
    else:
        return {"extracted_text": ""}

from google.cloud import translate
from storage_client import get_project_id

def stored_text_translate(text_to_translate: str, target_language_code: str = "es"):
    client = translate.TranslationServiceClient()

    parent = f"projects/{get_project_id()}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text_to_translate],
            "mime_type": "text/plain",  # Mime types: "text/plain", "text/html"
            "target_language_code": target_language_code,
        }
    )

    for translation in response.translations:
        return {"translated_text": translation.translated_text}
    return {"translated_text": ""}

